let tokens = canvas.tokens.controlled;
let number = canvas.tokens.controlled.length;
let title = `Mirror ${number} selected tokens?`;
if (number === 0) {
  ui.notifications.error("You must select at least one token");
  return;
}

const yesno = await foundry.applications.api.DialogV2.confirm({
  window: { title: title },
  content: `<p>All selected Spacecraft and Vehicle tokens will be flipped. Other token types will be ignored.</p>`,
  rejectClose: false,
  modal: true
});

if (yesno) {
  for (const token of tokens) {
    if (["vehicle", "spacecraft"].includes(token.document.actor.type)) {
      const texture = token.document.texture;
      texture.scaleX = texture.scaleX * -1;
      texture.scaleY = texture.scaleY * -1;
      token.document.update({ texture: texture });
    }
  }
} else {
  console.log("No");
}
